recipes.code:
{
  "inputs": [
    {
      "id": "openai-ads-api-key",
      "type": "promptString",
      "description": "OpenAI Ads API key from Ads Manager. Scoped to one ad account.",
      "password": true
    }
  ],
  "servers": {
    "openai-ads": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "openai-ads-mcp@0.1.7"
      ],
      "env": {
        "OPENAI_ADS_API_KEY": "${input:openai-ads-api-key}",
        "OPENAI_ADS_MCP_READONLY": "1",
        "OPENAI_ADS_BUDGET_CEILING_USD": "100"
      }
    }
  }
}
